INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64901021', 64901021, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Dinas Pekerjaan Umum, Perumahan dan Kawasan Permukiman', 'Belanja Jasa Konsultansi Beriorientasi Layanan - Jasa Khusus', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 95000000, 'January 2026', 'APBD', 1, 1, '1 paket', 'Dalam rangka meningkatkan kinerja dan kualitas pelayanan pembinaan jasa konstruksi di Kota Yogyakarta, khususnya dalam merumuskan kebijakan dan penyiapan kegiatan pelatihan tenaga kerja konstruksi sebagai upaya pengembangan sumber daya manusia, peningkatan kapasitas kelembagaan jasa konstruksi, serta pelaksanaan pengawasan penyelenggaraan jasa konstruksi pada tahun 2025, maka diperlukan basis data yang detail, lengkap, dan mutakhir agar dapat dijadikan acuan yang valid dalam merencanakan dan melaksanakan kegiatan pembinaan dan pengembangan sumber daya manusia dan badan usaha jasa konstruksi di Kota Yogyakarta agar kompenten dan kompetitif. Penyusunan Profil Jasa Konstruksi Tahunan ini diperlukan untuk dapat memberikan penyediaan data dan informasi jasa konstruksi cakupan kabupaten/kota sesuai dengan layanan informasi jasa konstruksi yang dioperasikan oleh Dinas PUPKP Kota Yogyakarta serta Indikator Kinerja Kunci (IKK) bidang pembinaan jasa konstruksi. Dengan adanya data dan informasi tersebut dapat diketahui kondisi dan potensi sektor jasa konstruksi di Kota Yogyakarta.', 'Ruang lingkup substansi Pekerjaan Penyusunan Profil Jasa Konstruksi Tahunan meliputi hal-hal sebagai berikut : 1. Mengumpulkan data dan informasi terkait jasa konstruksi di Kota Yogyakarta pada tahun 2024-2025, 2. Menganalisa data dan informasi terkait jasa konstruksi yang diperoleh, 3. Menyajikan hasil pendataan dalam bentuk yang mudah dipahami dan informatif, sesuai dengan layanan informasi jasa konstruksi yang dioprasikan oleh daerah dan indikator kinerja kunci bidang pembinaan jasa konstruksi. 4. Menyediakan input basis data yang diintegrasikan dalam format database jasa konstruksi Kota Yogyakarta dalam SIJAKON dan melakukan entry data melalui jasakonstruksi.jogjakota.go.id 5. Menyampaikan rekomendasi berdasarkan hasil pendataan dan penyusunan profil jasa konstruksi. Kebutuhan data dan informasi sesuai dengan layanan informasi jasa konstruksi yang dioperasikan oleh Dinas PUPKP Kota Yogyakarta dan Indikator Kinerja Kunci pada bidang pembinaan jasa konstruksi adalah sebagai berikut : 1. Data Tenaga Kerja Konstruksi 2. Data Asosiasi Badan Usaha dan Profesi 3. Data Pelatihan Tenaga Kerja Konstruksi 4. Data Badan Usaha Jasa Konstruksi 5. Data TDUP 6. Data Badan Usaha Rantai Pasok 7. Data Potensi Pasar 8. Data Histori Pekerjaan Konstruksi 9. Data Pembinaan Jasa Konstruksi 10. Data Pengawasan Penyelenggaraan Jasa Konstruksi 11. Data K3 (Kecelakaan Kerja Konstruksi) 12. Data Peraturan Terkait Jasa Konstruksi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1840727);
