INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64926038', 64926038, 'analyze_legacy', 'Kota Tegal', 'kabkota', 'BLUD Puskesmas Debong Lor', 'Belanja Modal Peralatan dan Mesin BLUD - Belanja Modal Personal Komputer', 'Barang', 'E-Purchasing', 'Jawa Tengah, Tegal (Kota)', 80121100, 'February 2026', 'BLUD', 1, 1, '1 Paket', '(#) Komputer Office Low (#) Laptop core i5 (#) Tablet - spesifikasi : Low (#) Layar Monitor - Spesifikasi : 21.5 inch Wide', 'Spesifikasi Komputer office low yang ideal memiliki prosesor Intel Core i3/AMD Ryzen 3, RAM 8GB, dan SSD 256GB, cukup untuk aplikasi perkantoran standar (Microsoft Office, browsing, email) karena menawarkan kecepatan dan multitasking yang memadai, dengan grafis terintegrasi (integrated GPU) karena tidak membutuhkan kartu grafis khusus, serta menjalankan sistem operasi Windows 10/11 atau macOS. Spesifikasi laptop Core i5 sangat bervariasi, tapi umumnya mencakup prosesor Intel Core i5 (generasi terbaru seperti Gen 12, 13, 14), RAM minimal 8GB DDR4/DDR5, penyimpanan SSD 256GB/512GB NVMe, layar Full HD (1920x1080), dan seringkali kartu grafis terintegrasi (Intel Iris Xe) atau diskrit (NVIDIA GeForce RTX/MX) tergantung kebutuhan, ideal untuk produktivitas, multitasking, dan bahkan gaming ringan hingga menengah. Spesifikasi Tablet "low" atau entry-level menawarkan harga terjangkau untuk aktivitas dasar seperti browsing, nonton, dan tugas sekolah ringan, dengan contohnya Redmi Pad SE 8.7, Samsung Galaxy Tab A9, dan Huawei MatePad SE, yang umumnya memiliki RAM 3-4GB, penyimpanan 32-128GB, chipset kelas menengah (seperti MediaTek Helio G85), dan fitur dasar seperti baterai cukup besar dan layar HD/FHD. Spesifikasi Layar monitor 21.5 inci wide umumnya memiliki resolusi Full HD (1920x1080), rasio aspek 16:9, panel IPS atau VA untuk sudut pandang luas, dan kecepatan refresh standar 60Hz atau 75Hz, cocok untuk penggunaan sehari-hari, kerja, dan multimedia dengan ukuran fisik diagonal sekitar 54.6 cm. Spesifikasi detail bisa bervariasi antar merek seperti Acer, BenQ, Lenovo, atau LG, namun inti dari "21.5 inch Wide" adalah ukuran dan form factor layarnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1846014);
