INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64903914', 64903914, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Konsultan Ahli Menteri Bidang Kebijakan Fiskal dan Moneter, Perencanaan Pembangunan Ekonomi, Analisis Ekonomi Global, Pengembangan Kapasitas Institusi Keuangan Tahun Anggaran 2026.', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 192600000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Pengadaan Konsultan Ahli Menteri Bidang Kebijakan Fiskal dan Moneter, Perencanaan Pembangunan Ekonomi, Analisis Ekonomi Global, Pengembangan Kapasitas Institusi Keuangan merupakan penugasan kepada individu yang akan bertanggungjawab untuk membantu dan mendukung kegiatan yang sesuai dengan bidang keahlian secara profesional untuk mendorong terbentuknya tata kelola pemerintahan yang baik, transparan dan profesional dengan berorientasi pada arahan Menteri PPN/Kepala Bappenas sesuai Standar Kompetensi Nasional pada Tahun Anggaran 2026.', 'Secara umum lingkup kegiatan dari Konsultan Ahli Menteri Bidang Kebijakan Fiskal dan Moneter, Perencanaan Pembangunan Ekonomi, Analisis Ekonomi Global, Pengembangan Kapasitas Institusi Keuangan adalah menganalisis, melaksanakan program-program, dan merancang kebijakan. Adapun hasil dari rencana strategis kerja akan menjadi rujukan dalam menyusun kerangka kerja terkait bidang keahliannya. Ruang lingkup kegiatan/pekerjaan Konsultan Ahli Menteri Bidang Kebijakan Fiskal dan Moneter, Perencanaan Pembangunan Ekonomi, Analisis Ekonomi Global, Pengembangan Kapasitas Institusi Keuangan meliputi: Memberikan rekomendasi kebijakan fiskal dan moneter untuk memastikan stabilitas ekonomi makro dan mendukung pertumbuhan ekonomi yang berkelanjutan. Memberikan rekomendasi rencana pembangunan ekonomi. Memberikan analisis mengenai dampak faktor-faktor ekonomi global terhadap perekonomian Indonesia, serta memberikan rekomendasi kebijakan untuk mitigasi risiko eksternal. Membantu dalam pengembangan kapasitas institusi keuangan negara untuk meningkatkan efektivitas perencanaan dan pengelolaan keuangan publik. Menyusun policy notes/policy brief per bulan terkait isu-isu seputar Bidang Kebijakan Fiskal dan Moneter, Perencanaan Pembangunan Ekonomi, Analisis Ekonomi Global, Pengembangan Kapasitas Institusi Keuangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1848474);
